async handleFetchAgentTimelineRequest(msg, source) {
    const direction = msg.direction ?? (msg.cursor ? "after" : "tail");
    const projection = "projected";
    const requestedLimit = msg.limit;
    const pageLimit = requestedLimit ?? (direction === "after" ? 0 : 200);
    const cursor = msg.cursor
        ? {
            epoch: msg.cursor.epoch,
            seq: msg.cursor.seq,
        }
        : undefined;
    try {
        const snapshot = await ensureAgentLoaded(msg.agentId, {
            agentManager: this.agentManager,
            agentStorage: this.agentStorage,
            logger: this.sessionLogger,
        });
        const agentPayload = await this.buildAgentPayload(snapshot);
        const fetchedControlTimeline = this.agentManager.fetchTimeline(msg.agentId, {
            direction,
            cursor,
            limit: pageLimit,
        });
        const selectedTimeline = {
            timeline: fetchedControlTimeline,
            entries: fetchedControlTimeline.rows,
            startSeq: fetchedControlTimeline.startSeq,
            endSeq: fetchedControlTimeline.endSeq,
            hasOlder: fetchedControlTimeline.hasOlder,
            hasNewer: fetchedControlTimeline.hasNewer,
        };
        const startCursor = selectedTimeline.startSeq !== null
            ? { epoch: selectedTimeline.timeline.epoch, seq: selectedTimeline.startSeq }
            : null;
        const endCursor = selectedTimeline.endSeq !== null
            ? { epoch: selectedTimeline.timeline.epoch, seq: selectedTimeline.endSeq }
            : null;
        const entries = selectedTimeline.entries.filter((entry) => this.supportsTimelineItem(entry.item, source));
        this.emitForSource({
            type: "fetch_agent_timeline_response",
            payload: {
                requestId: msg.requestId,
                agentId: msg.agentId,
                agent: agentPayload,
                direction,
                projection,
                epoch: selectedTimeline.timeline.epoch,
                reset: fetchedControlTimeline.reset,
                staleCursor: fetchedControlTimeline.staleCursor,
                gap: fetchedControlTimeline.gap,
                window: selectedTimeline.timeline.window,
                startCursor,
                endCursor,
                hasOlder: selectedTimeline.hasOlder,
                hasNewer: selectedTimeline.hasNewer,
                ...(msg.mergeWindow === true ? { mergeWindow: true } : {}),
                entries: entries.map((entry) => {
                    const payloadEntry = {
                        provider: snapshot.provider,
                        item: entry.item,
                        timestamp: entry.timestamp,
                        seqStart: entry.seqStart,
                        seqEnd: entry.seqEnd,
                        sourceSeqRanges: entry.sourceSeqRanges,
                        turnId: undefined,
                        collapsed: (source
                            ? this.supportsForSource(CLIENT_CAPS.reasoningMergeEnum, source)
                            : this.supports(CLIENT_CAPS.reasoningMergeEnum))
                            ? entry.collapsed
                            : entry.collapsed.filter((value) => value !== "reasoning_merge"),
                    };
                    payloadEntry.turnId = entry.turnId;
                    return payloadEntry;
                }),
                error: null,
            },
        }, source);
    }
    catch (error) {
        this.sessionLogger.error({ err: error, agentId: msg.agentId }, "Failed to handle fetch_agent_timeline_request");
        this.emitForSource({
            type: "fetch_agent_timeline_response",
            payload: {
                requestId: msg.requestId,
                agentId: msg.agentId,
                agent: null,
                direction,
                projection,
                epoch: "",
                reset: false,
                staleCursor: false,
                gap: false,
                window: { minSeq: 0, maxSeq: 0, nextSeq: 0 },
                startCursor: null,
                endCursor: null,
                hasOlder: false,
                hasNewer: false,
                ...(msg.mergeWindow === true ? { mergeWindow: true } : {}),
                entries: [],
                error: error instanceof Error ? error.message : String(error),
            },
        }, source);
    }
}

