async handleAgentTimelineSearchRequest(msg, source) {
    try {
        await ensureAgentLoaded(msg.agentId, {
            agentManager: this.agentManager,
            agentStorage: this.agentStorage,
            logger: this.sessionLogger,
        });
        const rows = await this.agentManager.getTimelineRows(msg.agentId);
        const { epoch } = this.agentManager.fetchTimeline(msg.agentId, {
            direction: "tail",
            limit: 1,
        });
        const result = await searchTimeline({ rows, query: msg.query, cursor: msg.cursor });
        if (this.agentManager.fetchTimeline(msg.agentId, { direction: "tail", limit: 1 }).epoch !==
            epoch) {
            throw new Error("History changed; search again");
        }
        this.emitForSource({
            type: "agent.timeline.search.response",
            payload: {
                requestId: msg.requestId,
                agentId: msg.agentId,
                epoch,
                ...result,
                error: null,
            },
        }, source);
    }
    catch (error) {
        this.emitForSource({
            type: "agent.timeline.search.response",
            payload: {
                requestId: msg.requestId,
                agentId: msg.agentId,
                epoch: "",
                locations: [],
                nextCursor: null,
                error: error instanceof Error ? error.message : String(error),
            },
        }, source);
    }
}

